import i18n from "@/i18n"
import { isLikelyOpaqueId } from "@/features/content/lib/content-display"
import type { PipelinePageItem } from "@/shared/types/pipeline.type"

const AUTO_WORKFLOW_NAME = /^Workflow for rule [0-9a-f-]+$/i

export function isAutoGeneratedWorkflowName(name: string | undefined): boolean {
  const trimmed = name?.trim()
  if (!trimmed) return true
  if (AUTO_WORKFLOW_NAME.test(trimmed)) return true
  return isLikelyOpaqueId(trimmed)
}

/** User-facing workflow label — never show auto-generated id-based names. */
export function displayWorkflowLabel(name: string | undefined): string {
  const trimmed = name?.trim()
  if (!trimmed || isAutoGeneratedWorkflowName(trimmed)) {
    return i18n.t("pipeline:toolbar.unnamedWorkflow")
  }
  return trimmed.length > 48 ? `${trimmed.slice(0, 48)}…` : trimmed
}

/** Campaign / rule label for pipeline cards. */
export function displayPipelineRuleName(
  ruleName: string | undefined,
  ruleRef: string | undefined,
): string | null {
  const trimmed = ruleName?.trim()
  if (trimmed && !isLikelyOpaqueId(trimmed)) return trimmed
  if (ruleRef?.trim() && !isLikelyOpaqueId(ruleRef)) {
    const ref = ruleRef.trim()
    return ref.length > 48 ? `${ref.slice(0, 48)}…` : ref
  }
  return null
}

function normalizeText(value: string | undefined): string {
  return value?.trim().toLowerCase() ?? ""
}

export function pipelineCardPrimaryTitle(
  item: PipelinePageItem,
  fallback: string,
): string {
  const name = item.name?.trim()
  const prompt = item.contentPrompt?.trim()
  if (name) return name
  if (prompt) return prompt.length > 140 ? `${prompt.slice(0, 137)}…` : prompt
  return fallback
}

export function pipelineCardSecondaryPrompt(item: PipelinePageItem): string | null {
  const name = item.name?.trim()
  const prompt = item.contentPrompt?.trim()
  if (!prompt) return null
  if (normalizeText(name) === normalizeText(prompt)) return null
  if (!name) return null
  return prompt.length > 120 ? `${prompt.slice(0, 117)}…` : prompt
}
